// TH18 v1.00a Stage 3 wave 03: st03.ecl.txt:1121-1140 (MainSub02/02b).
// Enemies: GirlC01 (st03:609-693) x2 and Phantom01 (st03:1270-1338) x7.
// Source parent for both creations is the stage main at (0,0); no boss state.
const TIME_LIMIT: int = 1000;
const TH18_BIG_BALL: int = 640; // type 18, radius 8.5, color 3
const TH18_BALL: int = 416;     // type 4, radius 4, color 4

// st03:663-673 / 1299-1301: etEx type2 a=1 ANIM retreats 4*spawn speed.
// GirlC01: etEx type2097152 a=120, r=2.5(E)/3.5(NHL), s=-9999994 (current angle).
xformdef C01_ACCEL_SLOW {
    @120 set_accel(0.0083333333fx);
    set_accel(0fx);
}
xformdef C01_ACCEL_FAST {
    @120 set_accel(0.0166666667fx);
    set_accel(0fx);
}
// Phantom01: etEx WAIT 60, then 2097152 a=80 to speed 2.0 along the fixed angle.
xformdef PHANTOM_VEL {
    @60 add_speed(0fx);
    @80 set_accel(0.0225fx);
    set_accel(0fx);
}

// st03:635-693 GirlC01_at. et shared by this enemy only; one burst owner.
async sub c01_fire() {
    var rank: int = global(GVAR_RANK);
    var n: int = 4;
    var delta: angle = 30deg;
    var rounds: int = 5;
    var interval: int = 60;
    if rank == 1 {
        rounds = 20;
        interval = 20;
    } else if rank == 2 {
        n = 6;
        delta = 20deg;
        rounds = 20;
        interval = 20;
    } else if rank == 3 {
        n = 8;
        delta = 15deg;
        rounds = 20;
        interval = 20;
    }
    wait(rand(60)); // st03:638 $RAND % 60
    sh_reset(0);
    sh_sprite(0, TH18_BIG_BALL, 3);
    sh_aim(0, 1);   // etAim(0,0): aimed fan
    sh_ring(0, 0);
    sh_count(0, n, 1);
    sh_angle(0, 0deg, delta);
    sh_speed(0, 1.5fx, 0fx); // etSpeed(1.5,1.5), one layer
    sh_dist(0, -6fx);        // ANIM a=1: -4*1.5
    if rank == 0 {
        sh_xform(0, C01_ACCEL_SLOW);
    } else {
        sh_xform(0, C01_ACCEL_FAST);
    }
    for i in 0..rounds {
        sh_fire(0); // st03:678 etOn(0)
        wait(interval);
    }
}

// st03:609-633 GirlC01 main. moveVel(pi/2,2) then three moveVelTime(80,mode1).
async sub girl_c01() {
    set_invuln(65535);
    set_hurtbox(16fx); // source 32x32 -> radius 16
    set_hitbox(12fx);  // source 24x24 -> radius 12
    spawn c01_fire();  // st03:622, starts one frame later
    var t: int = 0;
    loop {
        var u: fx = 0fx;
        var v: fx = 0fx;
        if t < 80 {
            u = (t as fx) / 80fx;
            v = 2fx - 2fx * u * u; // 2 -> 0, QUAD_IN
        } else if t < 130 {
            v = 0fx;
        } else if t < 210 {
            u = ((t - 130) as fx) / 80fx;
            v = 0.2fx * u * u; // 0 -> 0.2, QUAD_IN
        } else if t < 510 {
            v = 0.2fx;
        } else if t < 590 {
            u = ((t - 510) as fx) / 80fx;
            v = 0.2fx + 1.2fx * u * u; // 0.2 -> 1.4, QUAD_IN
        } else {
            v = 1.4fx;
        }
        move_vel_xy(0, 0fx, v, EASE_LINEAR);
        t = t + 1;
        wait(1);
    }
}

// st03:1289-1337 Phantom01_at: one aimed bullet after the rank wait.
async sub phantom_fire() {
    var rank: int = global(GVAR_RANK);
    if rank >= 2 {
        wait(10);
    } else {
        wait(60);
    }
    sh_reset(0);
    sh_sprite(0, TH18_BALL, 4);
    sh_aim(0, 0); // etAim(0,1): fixed-direction fan, n=1
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    sh_angle(0, aim_player(), 0deg); // st03:1320 %ANGLE_PLAYER
    sh_speed(0, 0.2fx, 0fx);
    sh_dist(0, -0.8fx); // ANIM a=1: -4*0.2
    sh_xform(0, PHANTOM_VEL);
    // st03:1315 unless (($DIFF != 0) || (($RAND % 3) == 0)); RAND only for E.
    if rank != 0 {
        sh_fire(0);
    } else if rand(3) == 0 {
        sh_fire(0);
    }
    if rank == 2 {
        wait(35);
    } else if rank == 3 {
        wait(20);
    } else {
        wait(60);
    }
}

// st03:1270-1287 Phantom01. moveEllipseRel(theta0, 2deg/f, r=10, d=0, beta=0, s=0)
// with beta=ABS_ANGLE=0 before the first moveVel, so REL is purely vertical:
// final = ABS(t) + 10*sin(theta0 + 2deg*t). ABS: 120-frame linear 0 -> 2 downward.
async sub phantom() {
    set_invuln(65535);
    set_hurtbox(14fx); // source 28x28 -> radius 14
    set_hitbox(8fx);   // source 16x16 -> radius 8
    var x0: fx = $self_x;
    var abs_y: fx = $self_y;
    var theta: angle = rand(65536) as angle; // %RANDRAD
    move_to(0, x0, abs_y + 10fx * sin(theta), EASE_LINEAR); // setter composes immediately
    spawn phantom_fire();
    var t: int = 0;
    loop {
        var v: fx = 2fx;
        if t < 120 {
            v = 2fx * (t as fx) / 120fx; // moveVelTime mode0
        }
        abs_y = abs_y + v;
        theta = theta + 2deg;
        move_vel_xy(0, 0fx, abs_y + 10fx * sin(theta) - $self_y, EASE_LINEAR);
        t = t + 1;
        wait(1);
    }
}

// st03:1129-1140 MainSub02b: seven Phantom01 every 40 frames.
async sub phantom_scheduler() {
    for i in 0..7 {
        var ux: fx = (rand(65536) - 32768) as fx / 32768;
        var px: fx = ux * 80fx;
        var uy: fx = (rand(65536) - 32768) as fx / 32768;
        var py: fx = 80fx + uy * 32fx;
        _ = spawn_enemy(px, py, 120, 0, 0, 0, phantom);
        wait(40);
    }
}

// st03:1121-1127 MainSub02: two GirlC01 simultaneously, then async MainSub02b.
async sub wave() {
    wait(120); // shell buffer before the attack
    _ = spawn_enemy(-128fx, -48fx, 800, 0, 0, 0, girl_c01);
    _ = spawn_enemy(128fx, -48fx, 800, 0, 0, 0, girl_c01);
    spawn phantom_scheduler();
    loop { wait(600); }
}

async sub controller() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 10000, 0, 0, 0, controller);
    loop { wait(600); }
}
